const allGlobals = global || [];
const myName = (avatar || '').toLowerCase();
const pinned = (param('pinnedName') || '').toLowerCase();
const mode = (param('viewMode') || 'all').toLowerCase();
const rawLogs = Array.isArray(raw) ? raw : [];

let filtered = allGlobals;
if (mode === 'mine') filtered = allGlobals.filter(g => g.player.toLowerCase() === myName);
if (mode === 'pinned') filtered = allGlobals.filter(g => g.player.toLowerCase() === pinned);

const isAll = mode === 'all';
const isMine = mode === 'mine';
const isPinned = mode === 'pinned';

// Sort by time descending, then take the last 50 (most recent)
const list = filtered.sort((a, b) => b.time - a.time).slice(0, 50).map(g => {
  let logEntry = null;
  for (let i = 0; i < rawLogs.length; i++) {
    const r = rawLogs[i];
    if (r.channel === 'Globals' && r.data && r.data.global && 
        r.data.global.player === g.player && 
        Math.floor(r.data.global.value) === Math.floor(g.value)) {
      logEntry = r;
      break;
    }
  }
  return {
    player: g.player,
    mob: g.name,
    value: Math.floor(g.value),
    isHoF: g.isHoF,
    isATH: g.isATH,
    isMe: myName && g.player.toLowerCase() === myName,
    isPinned: pinned && g.player.toLowerCase() === pinned,
    msg: logEntry ? logEntry.message : ''
  };
});

cssTemplate:
.root { width: 280px; font-family: 'Segoe UI', sans-serif; color: #fff; }
.tabs { display: flex; gap: 2px; margin-bottom: 4px; }
.tab { flex: 1; background: rgba(50, 50, 50, 0.4); padding: 6px; font-size: 10px; text-align: center; cursor: pointer; font-weight: bold; border-bottom: 2px solid transparent; transition: all 0.2s; }
.tab.active { background: rgba(80, 80, 80, 0.6); color: #ffd700; border-bottom: 2px solid #ffd700; }

.list-container {
  display: flex;
  flex-direction: column;
  gap: 2px;
  max-height: 380px;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: #ffd700 transparent;
}

.list-container::-webkit-scrollbar { width: 4px; }
.list-container::-webkit-scrollbar-thumb { background: #ffd700; border-radius: 2px; }

.entry {
  background: rgba(20, 20, 20, 0.3);
  display: flex;
  justify-content: space-between;
  padding: 6px 8px;
  border-left: 2px solid transparent;
  flex-shrink: 0;
}

.entry.me { border-left-color: #00ffcc; background: rgba(0, 255, 204, 0.1); }
.entry.hof { border-left-color: #ffd700; }
.entry.ath { border-left-color: #ff4444; background: rgba(255, 68, 68, 0.1); }

.p-row { display: flex; align-items: center; justify-content: space-between; gap: 6px; }
.btn-group { display: flex; gap: 4px; }
.p-name { font-size: 11px; font-weight: bold; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100px; }
.pin-btn, .copy-btn { font-size: 10px; cursor: pointer; opacity: 0.5; transition: opacity 0.2s; }
.pin-btn:hover, .copy-btn:hover { opacity: 1; }
.m-name { font-size: 9px; color: #bbb; }
.amount { color: #ffd700; font-weight: bold; font-size: 12px; align-self: center; }
.empty { text-align: center; font-size: 10px; padding: 20px; color: #888; }
